const people={alex:{name:'Alex Morgan',role:'Senior product designer',initials:'AM',years:'6 years at Aster',bio:'Connects product decisions with their history. Interested in how new research can challenge established approaches.',skills:['Patient portals','Research history','Product strategy']},christine:{name:'Christine Weber',role:'Patient-services specialist',initials:'CW',years:'8 years at Aster',bio:'Brings recurring patient questions and service workflows into product conversations. Curious about better ways to investigate misunderstandings.',skills:['Patient communication','Service workflows','Appointment preparation']},jonas:{name:'Jonas Keller',role:'Software engineer',initials:'JK',years:'4 years at Aster',bio:'Explains the constraints behind the portal and looks for opportunities to revisit them as the product changes.',skills:['Portal architecture','Content delivery','Technical constraints']},maya:{name:'Maya Chen',role:'Product designer',initials:'MC',years:'3 weeks at Aster',bio:'New to healthcare, with three years in a creative and e-commerce team doing graphic and UX/UI design. Brings accessibility and usability-testing experience.',skills:['Accessibility','UX/UI design','Usability testing']}};
Object.assign(people,{
  elena:{name:'Elena Rossi',role:'Content designer',initials:'ER',years:'1 year at Aster',bio:'Works on the words people see in appointment messages and the portal. Interested in how teams explain the same service in different ways.',skills:['Plain language','Content design','Service terminology']},
  samir:{name:'Samir Patel',role:'Accessibility specialist',initials:'SP',years:'2 months at Aster',bio:'Brings experience testing digital services with assistive technology. Wants to understand how accessibility decisions are carried from design into delivery.',skills:['Assistive technology','Inclusive research','Accessibility reviews']},
  nina:{name:'Nina Baumann',role:'Clinical product specialist',initials:'NB',years:'10 years at Aster',bio:'Helps teams understand clinical workflows and identify questions that need clinical review. Curious about how prototypes can make those conversations easier.',skills:['Clinical workflows','Product review','Care coordination']},
  luca:{name:'Luca Bianchi',role:'Customer implementation lead',initials:'LB',years:'5 years at Aster',bio:'Helps clinics introduce the portal into their daily work. Shares what changes between a product demonstration and the way a service is actually used.',skills:['Clinic onboarding','Service adoption','Customer feedback']},
  ines:{name:'Inès Dubois',role:'Data analyst',initials:'ID',years:'7 months at Aster',bio:'Connects product questions with patterns in service usage. Interested in combining quantitative signals with colleagues’ observations before drawing conclusions.',skills:['Product analytics','Research questions','Measurement']}
});

const seed=[
{id:'instructions',type:'Tested finding',title:'Patients understood the words, but weren’t sure which instructions to follow.',excerpt:'We simplified the language. Patients still weren’t sure which instructions applied to their appointment.',person:'alex',topic:'Patient experience',tags:['Appointment preparation','Research'],date:'12 Sep 2026',context:'An earlier exploratory study of the appointment-preparation page. Six moderated sessions; findings were specific to the tested version.',happened:'We expected shorter sentences to make the page easier to use. Four of six participants could explain the wording, but still asked whether the instructions were relevant to their appointment type.',learning:'Understanding an instruction and recognizing that it applies to you are different problems. We recommended checking how people identify their appointment type before rewriting the instructions again. We have not yet tested a solution.',limits:'Six sessions with one version of the page. It does not show that the same issue affects every appointment type or that the revised draft resolves it.',prompt:'How could your study distinguish understanding the words from knowing which instructions apply?'},
{id:'phone',type:'Observation',title:'Patients call to ask which preparation instructions apply to them.',excerpt:'A recurring question in patient-service conversations, even when the preparation page has been read.',person:'christine',topic:'Patient experience',tags:['Patient questions','Service context'],date:'21 Oct 2026',context:'An informal observation from patient-service conversations about appointment preparation. This is not a counted or representative sample.',happened:'Some callers say they have read the preparation page, then ask us to confirm which part applies to their appointment. The concern is not always the meaning of the text.',learning:'We may need to investigate how people connect general instructions to their own situation. I would like to compare the questions people ask with what we ask in our research sessions.',limits:'Anecdotal and potentially biased toward people who contact us. We do not know the frequency or the experiences of patients who never call.',prompt:'What would you ask a participant before showing them the instructions?'},
{id:'constraints',type:'Perspective',title:'Why we put instructions for different appointments on one page.',excerpt:'Why the shared preparation page exists—and which parts of that decision we can revisit.',person:'jonas',topic:'Product decisions',tags:['Technical context','Decision history'],date:'07 Oct 2026',context:'The portal used to show everyone the same preparation page. Keeping one page updated was easier than maintaining a separate page for each appointment type. The system can now identify the appointment type associated with a booking.',happened:'We grouped instructions for different appointments on one page so staff would not have to update the same information in several places. Patients then had to work out which sections applied to them.',learning:'Now that the portal can identify the booked appointment type, we could explore showing only the relevant preparation information. Engineering and the content owners still need to check how this would work.',limits:'This explains a past trade-off, not an approved implementation plan. Feasibility and content ownership still need review.',prompt:'Which assumptions about the current page should your team check again?'},
{id:'leading',type:'Perspective',title:'Our test questions might tell patients where to look.',excerpt:'A technique from another sector that could help us ask more useful research questions.',person:'maya',topic:'Research methods',tags:['Usability testing','Fresh perspective'],date:'28 Oct 2026',context:'Experience from a creative and e-commerce team, brought into planning for the patient-portal study.',happened:'In earlier projects, we noticed that tasks repeating the interface labels made it easier for participants to find the intended route without showing whether that route made sense to them.',learning:'Describe the person’s goal and situation, rather than telling them what to click or read. For this project, we could ask what they would do before an appointment and observe what information they seek.',limits:'An approach from another context, not a tested finding about healthcare. Clinical and research colleagues should review the task for realism.',prompt:'Could you rewrite one study task around a patient’s goal instead of the page labels?'},
{id:'question',type:'Open question',title:'Should our study start with the appointment confirmation?',excerpt:'Could the information people bring with them explain some of the confusion we see?',person:'alex',topic:'Research methods',tags:['Open question','Study planning'],date:'26 Oct 2026',context:'A question raised while revisiting the appointment-preparation study.',happened:'Our draft asks participants to start on the preparation page. In real life, patients may arrive there from an appointment-confirmation message. We have not yet checked whether the appointment names and links in that message help them find the right information.',learning:'We should consider the journey into the page, including the expectations set by messages and staff conversations.',limits:'An untested question. We need evidence before deciding whether the surrounding journey is the main issue.',prompt:'What context would make your research scenario more realistic?'},
{id:'handover',type:'Observation',title:'The next team found our design, but not why we chose it.',excerpt:'What we learned when another team picked up a design decision after a handover.',person:'jonas',topic:'Team learning',tags:['Handover','Shared reasoning'],date:'02 Oct 2026',context:'A handover between two product teams working on shared portal components.',happened:'The team taking over the project found the final design, but could not find why we chose it or which alternatives we had considered. They reopened a question we thought was settled, and also identified a constraint that had changed.',learning:'A useful handover includes why we chose an approach, what was rejected and which conditions could make us reconsider.',limits:'One handover experience, not evidence that all teams have the same issue.',prompt:'What would help another colleague know when to revisit your decision?'}
];
const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
let entries=[...seed,...load('wwk-contributions',[])],saved=load('wwk-saved',[]),notes=load('wwk-notes',[]),view='explore',filter='All experiences',query='',current=null;
const $=s=>document.querySelector(s);const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){localStorage.setItem('wwk-saved',JSON.stringify(saved));localStorage.setItem('wwk-notes',JSON.stringify(notes));localStorage.setItem('wwk-contributions',JSON.stringify(entries.filter(e=>e.id.startsWith('local-'))));$('#nav-count').textContent=notes.length;$('#nav-count').hidden=notes.length===0;$('#nav-count').title='Connected experiences'}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function badge(e){return `<span class="badge ${e.type==='Observation'?'observation':e.type==='Perspective'?'perspective':e.type==='Open question'?'question':''}">${escape(e.type)}</span>`}
function avatar(key){const p=people[key];return `<span class="avatar ${key}"><span aria-hidden="true">${p.initials}</span><img class="employee-portrait" src="assets/people/${key}.jpg" alt="" loading="lazy" decoding="async"></span>`}
function card(e){const p=people[e.person];return `<article class="card"><div class="card-body" tabindex="0" role="button" data-open="${e.id}" aria-label="Read ${escape(e.title)}"><div class="card-top">${badge(e)}<button class="save ${saved.includes(e.id)?'saved':''}" data-save="${e.id}" aria-label="${saved.includes(e.id)?'Unsave':'Save'} experience" aria-pressed="${saved.includes(e.id)}">${saved.includes(e.id)?'▰':'▱'}</button></div><h3>${escape(e.title)}</h3><p>${escape(e.excerpt)}</p><div class="card-tags">${e.tags.map(t=>`<span class="tag">${escape(t)}</span>`).join('')}</div></div><button class="card-footer" data-open="${e.id}">${avatar(e.person)}<span class="person-name">${p.name}<small>${p.role}</small></span><span class="arrow">↗</span></button></article>`}
function banner(){return `<section class="project-banner"><div><span class="eyebrow">YOUR CURRENT CHALLENGE · PATIENT PORTAL</span><h2>Do patients know which instructions apply to them?</h2><p>You’re preparing a usability study. Bring the team’s experience into your next question.</p><div class="intro-line">${avatar('maya')} Maya’s first project at Aster <span>·</span> Study preparation</div></div><button class="secondary" data-nav="project">Open project notebook ↗</button></section>`}
function renderCards(){let list=entries.filter(e=>(view!=='saved'||saved.includes(e.id))&&(filter==='All experiences'||e.topic===filter)&&(e.title+' '+e.excerpt+' '+e.tags.join(' ')+' '+people[e.person].name).toLowerCase().includes(query.toLowerCase()));$('#cards').innerHTML=list.length?list.map(card).join(''):`<div class="empty">${view==='saved'&&!saved.length?'Save an experience to return to it later.':'No experiences match this search. Try another word or topic.'}</div>`;$('#result-count').textContent=list.length+(list.length===1?' experience':' experiences');}
function render(){document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));$('#crumb').textContent=({explore:'Explore',saved:'Saved',project:'My project',people:'Our people'})[view];
if(view==='explore'||view==='saved'){$('#content').innerHTML=`<div class="page-heading"><div><span class="eyebrow">KNOWLEDGE GROWS BETWEEN US</span><h1>${view==='saved'?'A perspective to come back to.':'What could we see differently?'}</h1><p>${view==='saved'?'Your collection of experiences worth revisiting.':'Explore the experiences behind our work. Add a perspective of your own.'}</p></div><button class="primary" data-action="contribute">Share an experience <span>＋</span></button></div>${view==='explore'?banner():''}<div class="section-heading"><h2>${view==='saved'?'Saved for later':'From across the team'}</h2><span id="result-count"></span></div><div class="search"><span aria-hidden="true">⌕</span><input id="search" aria-label="Search experiences" placeholder="Search a challenge, topic or colleague…" value="${escape(query)}"></div><div class="filters">${['All experiences','Patient experience','Research methods','Product decisions','Team learning'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><div id="cards" class="cards"></div><div class="bottom-note">Real work. Different perspectives. Shared learning. <span>✳</span></div>`;renderCards();}
if(view==='project'){$('#content').innerHTML=`<div class="page-heading"><div><span class="eyebrow">MY PROJECT</span><h1>Your appointment-preparation project.</h1><p>Maya’s conversations, notes and next steps in one place.</p></div><button class="secondary" data-nav="experiences">Explore experiences ↗</button></div><section class="project-header"><span class="eyebrow">PATIENT PORTAL / STUDY PREPARATION</span><h2>Do patients know which instructions apply to them?</h2><p>Plan the next study of how patients find preparation information. Keep the conversation, research materials and experiences that influence your decisions together here.</p><div class="project-status"><span>Maya Chen · Product designer</span><span>Working question · Open for revision</span></div></section><div class="section-heading"><h2>Perspectives shaping this project</h2><span>${notes.length} connected ${notes.length===1?'experience':'experiences'}</span></div>${notes.length?notes.map((n,i)=>{const e=entries.find(e=>e.id===n.id);return `<article class="note-card"><div class="notebook-title">${badge(e)}<button class="remove-note" data-remove="${i}">Remove connection</button></div><h3>${escape(e.title)}</h3><button class="inline-link" data-open="${e.id}">Read ${people[e.person].name.split(' ')[0]}’s experience ↗</button><p>HOW THIS INFORMS MY WORK</p><div class="quote">${escape(n.note)}</div></article>`}).join(''):`<div class="empty"><h3>Start with someone else’s experience.</h3><p>Explore an account, then choose “Use in my project” to record what it changes for you.</p><button class="primary" data-nav="experiences">Find a perspective ↗</button></div>`}<div class="note-card"><span class="eyebrow">YOUR CONTRIBUTION</span><h3>What are you bringing to the question?</h3><p>Share a method, a different interpretation or something you have learned. New to Aster doesn’t mean new to design.</p><button class="text-button" data-action="contribute">Add my perspective ↗</button></div>`;}
if(view==='people'){$('#content').innerHTML=`<div class="page-heading"><div><span class="eyebrow">OUR PEOPLE</span><h1>There’s more experience here<br>than a job title can tell you.</h1><p>Discover what colleagues bring—and what they’re curious about.</p></div></div><div class="people-grid">${Object.entries(people).map(([k,p])=>`<article class="person-card">${avatar(k)}<h2>${p.name}</h2><div class="muted">${p.role}<small>${p.years}</small></div><p>${p.bio}</p><div class="card-tags">${p.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div>${entries.some(e=>e.person===k)?`<p><button class="text-button" data-person="${k}">Explore contributions ↗</button></p>`:`<p class="muted">No shared experiences yet</p>`}</article>`).join('')}</div>`;}}
function openDetail(id){current=entries.find(e=>e.id===id);const e=current,p=people[e.person];$('#detail-content').innerHTML=`<div class="dialog-inner"><div class="dialog-top">${badge(e)}<button class="icon-button" data-action="close-detail" aria-label="Close experience">×</button></div><h2>${escape(e.title)}</h2><button class="detail-person" data-profile="${e.person}">${avatar(e.person)}<span>${p.name}<small>${p.role} · ${escape(e.date)}</small></span></button><div class="detail-body"><h3>The context</h3><p>${escape(e.context)}</p><h3>What happened</h3><p>${escape(e.happened)}</p><h3>What I took from it</h3><p>${escape(e.learning)}</p><div class="context-box"><strong>What to keep in mind</strong><br>${escape(e.limits)}</div><h3>A question to take into your work</h3><p>${escape(e.prompt)}</p></div></div><div class="dialog-actions"><button class="secondary" data-save="${e.id}">${saved.includes(e.id)?'Saved ✓':'Save for later'}</button><button class="primary" data-action="apply">Use in my project ↗</button></div><div id="apply-section"></div>`;$('#detail').showModal();}
document.addEventListener('click',ev=>{const b=ev.target.closest('button,[data-open]');if(!b)return;if(b.dataset.save){ev.stopPropagation();const id=b.dataset.save;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();if($('#cards'))renderCards();if($('#detail').open){const sb=$('#detail .dialog-actions [data-save]');if(sb)sb.textContent=saved.includes(id)?'Saved ✓':'Save for later'}toast(saved.includes(id)?'Saved for later':'Removed from saved');return}if(b.dataset.nav){view=b.dataset.nav;query='';filter='All experiences';render();window.scrollTo(0,0)}if(b.dataset.filter){filter=b.dataset.filter;document.querySelectorAll('.filter').forEach(x=>x.classList.toggle('active',x.dataset.filter===filter));renderCards()}if(b.dataset.open)openDetail(b.dataset.open);if(b.dataset.person){view='experiences';query=people[b.dataset.person].name;filter='All experiences';render()}if(b.dataset.profile){$('#detail').close();view='people';render()}if(b.dataset.remove!==undefined){notes.splice(Number(b.dataset.remove),1);persist();render();toast('Connection removed')}
switch(b.dataset.action){case'contribute':$('#contribute-form').reset();$('#form-dialog').showModal();break;case'close-form':$('#form-dialog').close();break;case'close-detail':$('#detail').close();break;case'apply':$('#apply-section').innerHTML=`<div class="apply-box"><label>How does this change your approach?<textarea id="application-note" placeholder="For example: I’ll ask participants how they identify which instructions apply, rather than only testing whether they understand the text."></textarea></label><button class="primary" data-action="connect">Connect to project ↗</button></div>`;$('#application-note').focus();break;case'connect':{const note=$('#application-note').value.trim();if(!note){$('#application-note').focus();return}notes.push({id:current.id,note});persist();$('#detail').close();view='project';render();toast('Experience connected to your project');break}case'about':alert('What We Know is a fictional prototype for a SUPSI student proposal. You are exploring as Maya, a new product designer. Open a conversation, review the work, contribute a reply, or connect a previous experience to your project. Changes stay in this browser. No messages are sent and no real company data is used. Employee portraits are AI-generated illustrations of fictional people.');break;}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.card-body')){e.preventDefault();openDetail(e.target.dataset.open)}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;renderCards()}});
$('#contribute-form').addEventListener('submit',ev=>{ev.preventDefault();const f=new FormData(ev.target),title=f.get('title').trim(),context=f.get('context').trim(),learning=f.get('learning').trim();if(!title||!context||!learning)return;entries.unshift({id:'local-'+Date.now(),type:f.get('type'),title,excerpt:learning.slice(0,150)+(learning.length>150?'…':''),person:'maya',topic:'Team learning',tags:['Your contribution','Patient portal'],date:new Date().toLocaleDateString('en-GB'),context,happened:learning,learning,limits:'A colleague’s account. Check its context and relevance before applying it to another project.',prompt:'How might this experience inform your current work?'});persist();$('#form-dialog').close();view='experiences';filter='All experiences';query='';render();toast('Your experience has been shared')});
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d)d.close()});persist();render();

// Keep initials as a fallback if an employee image is unavailable.
document.addEventListener('error',event=>{if(event.target.matches?.('img.employee-portrait'))event.target.remove();},true);
